package io.github.jesterportfolio.hearth.survival.rpg;

import java.util.*;import java.util.concurrent.*;import java.nio.charset.StandardCharsets;
import org.bukkit.*;import org.bukkit.block.*;import org.bukkit.block.data.Bisected;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.inventory.*;import org.bukkit.event.entity.*;import org.bukkit.event.player.*;
import net.kyori.adventure.text.Component;
import com.sk89q.worldedit.bukkit.BukkitAdapter;import com.sk89q.worldedit.math.BlockVector3;import com.sk89q.worldguard.protection.regions.*;import com.sk89q.worldguard.protection.flags.*;
import io.github.jesterportfolio.hearth.economy.RpgStore;import io.github.jesterportfolio.hearth.survival.housing.HousingProtection;

/** WG flag 표현과 간접 유출 차단을 분리한다. LIST는 건축 멤버십을 주지 않는다. */
public final class RpgObjects implements Listener,AutoCloseable {
    public record Key(UUID world,int x,int y,int z){}
    private final RpgRuntime r;private Map<Key,RpgStore.Acl> index=Map.of();
    public RpgObjects(RpgRuntime r){this.r=r;Bukkit.getPluginManager().registerEvents(this,r.plugin);}
    public RpgStore.Acl at(Location at){return at==null||at.getWorld()==null?null:index.get(new Key(at.getWorld().getUID(),at.getBlockX(),at.getBlockY(),at.getBlockZ()));}
    public boolean allowed(UUID player,Location at){var row=at(at);return row!=null&&row.permits(player);}
    public RpgStore.Acl selection(Player p){var block=Objects.requireNonNull(p.getTargetBlockExact(5));var state=block.getState();String type=block.getType().name();if(!(state instanceof Container)&&!Set.of("LEVER","STONE_BUTTON","OAK_BUTTON","CRAFTING_TABLE","ANVIL","ENCHANTING_TABLE","GRINDSTONE","SMITHING_TABLE","STONECUTTER","LOOM","CARTOGRAPHY_TABLE").contains(type)&&!type.endsWith("_DOOR")&&!type.endsWith("_TRAPDOOR")&&!type.endsWith("_FENCE_GATE"))throw new IllegalArgumentException("RPG_OBJECT_TYPE");
        int x=block.getX(),y=block.getY(),z=block.getZ(),x2=x,y2=y,z2=z;
        if(state instanceof Chest chest&&chest.getInventory().getHolder() instanceof DoubleChest both){var left=both.getLeftSide() instanceof BlockState b?b.getLocation():null;var right=both.getRightSide() instanceof BlockState b?b.getLocation():null;if(left==null||right==null)throw new IllegalStateException("DOUBLE_CHEST");x=Math.min(left.getBlockX(),right.getBlockX());z=Math.min(left.getBlockZ(),right.getBlockZ());x2=Math.max(left.getBlockX(),right.getBlockX());z2=Math.max(left.getBlockZ(),right.getBlockZ());}
        if(type.endsWith("_DOOR")&&block.getBlockData() instanceof Bisected b){if(b.getHalf()==Bisected.Half.TOP)y--;y2=y+1;}
        var world=block.getWorld();String key=r.runtime.economy().settings.realm()+"/"+world.getUID()+"/"+x+"/"+y+"/"+z;UUID id=UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8));var old=r.snapshot().objects().stream().filter(a->a.id().equals(id)).findFirst();if(old.isPresent()&&!old.get().owner().equals(p.getUniqueId()))throw new IllegalStateException("RPG_NOT_OWNER");return new RpgStore.Acl(id,p.getUniqueId(),world.getUID(),x,y,z,x2,y2,z2,old.map(RpgStore.Acl::mode).orElse(RpgStore.Mode.PRIVATE),old.map(RpgStore.Acl::allowed).orElse(Set.of()),old.map(RpgStore.Acl::revision).orElse(0L));
    }
    public void mode(Player p,RpgStore.Acl row,RpgStore.Mode mode){var selected=selection(p);if(!selected.id().equals(row.id()))throw new IllegalStateException("RPG_TARGET_CHANGED");var old=r.snapshot().objects().stream().filter(a->a.id().equals(row.id())).findFirst();if(mode==RpgStore.Mode.REMOVED){if(old.isPresent())r.change(p,()->r.store.removeObject(r.runtime.economy().context(p),old.get()));return;}var updated=new RpgStore.Acl(row.id(),row.owner(),row.world(),selected.x(),selected.y(),selected.z(),selected.x2(),selected.y2(),selected.z2(),mode,row.allowed(),row.revision());r.change(p,()->r.store.object(r.runtime.economy().context(p),updated,old.map(RpgStore.Acl::revision).orElse(-1L)));}
    public void command(Player p,String[] args){var row=selection(p);if(args.length==0){r.menu.object(p,row);return;}if(args.length!=2||!Set.of("allow","remove","허용","제외").contains(args[0])){p.sendMessage(Component.text("/보호 · /보호 허용 <접속 사용자> · /보호 제외 <접속 사용자>"));return;}var target=Bukkit.getPlayerExact(args[1]);if(target==null||!r.runtime.economy().admitted(target))throw new IllegalArgumentException("RPG_TARGET_ACCOUNT");var allowed=new HashSet<>(row.allowed());if(args[0].equals("allow")||args[0].equals("허용"))allowed.add(target.getUniqueId());else allowed.remove(target.getUniqueId());var old=r.snapshot().objects().stream().filter(a->a.id().equals(row.id())).findFirst();var updated=new RpgStore.Acl(row.id(),row.owner(),row.world(),row.x(),row.y(),row.z(),row.x2(),row.y2(),row.z2(),RpgStore.Mode.LIST,allowed,row.revision());r.change(p,()->r.store.object(r.runtime.economy().context(p),updated,old.map(RpgStore.Acl::revision).orElse(-1L)));}
    public CompletionStage<Void> apply(List<RpgStore.Acl> rows){var next=new HashMap<Key,RpgStore.Acl>();var managers=new HashSet<com.sk89q.worldguard.protection.managers.RegionManager>();for(var row:rows){if(row.mode()!=RpgStore.Mode.REMOVED)for(int x=row.x();x<=row.x2();x++)for(int y=row.y();y<=row.y2();y++)for(int z=row.z();z<=row.z2();z++){var key=new Key(row.world(),x,y,z);if(next.put(key,row)!=null)throw new IllegalStateException("RPG_OBJECT_OVERLAP");}var world=Bukkit.getWorld(row.world());if(world==null)continue;var manager=HousingProtection.manager(world);managers.add(manager);for(String suffix:List.of("allow","deny")){String id="hearth_object_"+row.id().toString().replace("-","")+"_"+suffix;var lo=BlockVector3.at(row.x(),row.y(),row.z());var hi=BlockVector3.at(row.x2(),row.y2(),row.z2());var old=manager.getRegion(id);if(old!=null&&(!old.getMinimumPoint().equals(lo)||!old.getMaximumPoint().equals(hi)||old.getPriority()!=1200))throw new IllegalStateException("RPG_OBJECT_REGION_CONFLICT");if(row.mode()==RpgStore.Mode.REMOVED){manager.removeRegion(id);continue;}var region=new ProtectedCuboidRegion(id,lo,hi);region.setPriority(1200);region.setFlag(Flags.PASSTHROUGH,StateFlag.State.ALLOW);region.getOwners().addPlayer(row.owner());if(row.mode()==RpgStore.Mode.LIST)row.allowed().forEach(region.getMembers()::addPlayer);
                for(var flag:List.of(Flags.CHEST_ACCESS,Flags.INTERACT,Flags.USE)){if(row.mode()==RpgStore.Mode.PUBLIC){region.setFlag(flag,StateFlag.State.ALLOW);region.setFlag(flag.getRegionGroupFlag(),RegionGroup.ALL);}else{region.setFlag(flag,suffix.equals("allow")?StateFlag.State.ALLOW:StateFlag.State.DENY);region.setFlag(flag.getRegionGroupFlag(),suffix.equals("allow")?RegionGroup.MEMBERS:RegionGroup.NON_MEMBERS);}}
                for(var flag:List.of(Flags.BLOCK_BREAK,Flags.BLOCK_PLACE))region.setFlag(flag,StateFlag.State.DENY);manager.addRegion(region);
            }}index=Map.copyOf(next);return r.runtime.economy().database().module("rpg_objects_wg_save",c->{for(var manager:managers)manager.save();return null;});}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void interact(PlayerInteractEvent e){if(e.getClickedBlock()!=null){var row=at(e.getClickedBlock().getLocation());if(row!=null&&!row.permits(e.getPlayer().getUniqueId()))e.setCancelled(true);}}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void open(InventoryOpenEvent e){var row=at(e.getInventory().getLocation());if(row!=null&&!row.permits(e.getPlayer().getUniqueId()))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void transfer(InventoryMoveItemEvent e){var from=at(e.getSource().getLocation());var to=at(e.getDestination().getLocation());if(from!=null&&from.mode()!=RpgStore.Mode.PUBLIC||to!=null&&to.mode()!=RpgStore.Mode.PUBLIC)e.setCancelled(true);}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void breakBlock(BlockBreakEvent e){if(at(e.getBlock().getLocation())!=null){e.setCancelled(true);e.getPlayer().sendMessage(Component.text("먼저 /보호 메뉴에서 보호를 해제해 주세요."));}}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void place(BlockPlaceEvent e){var block=e.getBlockPlaced();if(at(block.getLocation())!=null){e.setCancelled(true);return;}if(block.getState() instanceof Chest)for(var face:List.of(org.bukkit.block.BlockFace.NORTH,org.bukkit.block.BlockFace.SOUTH,org.bukkit.block.BlockFace.EAST,org.bukkit.block.BlockFace.WEST))if(at(block.getRelative(face).getLocation())!=null){e.setCancelled(true);return;}}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void explode(EntityExplodeEvent e){e.blockList().removeIf(b->at(b.getLocation())!=null);}
    @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void explode(BlockExplodeEvent e){e.blockList().removeIf(b->at(b.getLocation())!=null);}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void piston(BlockPistonExtendEvent e){if(e.getBlocks().stream().anyMatch(b->at(b.getLocation())!=null||at(b.getRelative(e.getDirection()).getLocation())!=null))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void piston(BlockPistonRetractEvent e){if(e.getBlocks().stream().anyMatch(b->at(b.getLocation())!=null||at(b.getRelative(e.getDirection()).getLocation())!=null))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void flow(BlockFromToEvent e){if(at(e.getToBlock().getLocation())!=null)e.setCancelled(true);}
    @EventHandler(priority=EventPriority.LOWEST,ignoreCancelled=true) public void entity(EntityChangeBlockEvent e){if(at(e.getBlock().getLocation())!=null)e.setCancelled(true);}
    public void close(){HandlerList.unregisterAll(this);index=Map.of();}
}
